import os
import re
import glob
import pytesseract
from PIL import Image
from openpyxl import Workbook
from datetime import datetime

IMG_DIR = "/app/workspace/dataset/img"
OUTPUT_FILE = "/app/workspace/stat_ocr.xlsx"

# Keywords sorted by priority (1 is highest)
PRIORITY_1 = ["GRAND TOTAL"]
PRIORITY_2 = ["TOTAL RM", "TOTAL: RM"]
PRIORITY_3 = ["TOTAL AMOUNT"]
PRIORITY_4 = ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"]

EXCLUSION = ["SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED"]

def extract_date(text):
    # YYYY-MM-DD
    match = re.search(r'\b(\d{4})-(\d{2})-(\d{2})\b', text)
    if match:
        return f"{match.group(1)}-{match.group(2)}-{match.group(3)}"

    # DD-MM-YYYY or DD/MM/YYYY or DD.MM.YYYY
    match = re.search(r'\b(\d{2})[-/.](\d{2})[-/.](\d{4})\b', text)
    if match:
        return f"{match.group(3)}-{match.group(2)}-{match.group(1)}"

    # DD MMM YYYY (e.g. 23 JAN 2019)
    match = re.search(r'\b(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})\b', text, re.IGNORECASE)
    if match:
        day, month_str, year = match.groups()
        try:
            date_obj = datetime.strptime(f"{day} {month_str} {year}", "%d %b %Y")
            return date_obj.strftime("%Y-%m-%d")
        except ValueError:
            pass

    # MMM DD YYYY (e.g. JAN 23 2019)
    match = re.search(r'\b([A-Za-z]{3})\s+(\d{1,2})[,\s]+(\d{4})\b', text, re.IGNORECASE)
    if match:
        month_str, day, year = match.groups()
        try:
            date_obj = datetime.strptime(f"{day} {month_str} {year}", "%d %b %Y")
            return date_obj.strftime("%Y-%m-%d")
        except ValueError:
            pass

    return None

def parse_amount(line):
    # Look for currency pattern: 1,234.56 or 1234.56 or 12.34
    # We assume 2 decimal places as per hint
    matches = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2})', line)
    if matches:
        # Return the last one found on the line
        val = matches[-1]
        return val.replace(',', '')
    return None

def extract_total(text):
    lines = text.split('\n')
    candidates = [] # (priority, value)

    for i, line in enumerate(lines):
        line_upper = line.upper()

        # Check exclusion
        if any(ex in line_upper for ex in EXCLUSION):
            continue

        priority = 0
        if any(k in line_upper for k in PRIORITY_1):
            priority = 1
        elif any(k in line_upper for k in PRIORITY_2):
            priority = 2
        elif any(k in line_upper for k in PRIORITY_3):
            priority = 3
        elif any(k in line_upper for k in PRIORITY_4):
            priority = 4

        if priority > 0:
            val = parse_amount(line)
            if val:
                candidates.append((priority, val))
            else:
                # Fallback to next line
                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    val_next = parse_amount(next_line)
                    if val_next:
                        candidates.append((priority, val_next))

    if not candidates:
        return None

    # Sort by priority (1 is best, so ascending)
    candidates.sort(key=lambda x: x[0])
    return candidates[0][1]

def process():
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    files = sorted(glob.glob(os.path.join(IMG_DIR, "*.jpg")))

    for fpath in files:
        fname = os.path.basename(fpath)
        try:
            text = pytesseract.image_to_string(Image.open(fpath))

            date_str = extract_date(text)
            total_str = extract_total(text)

            ws.append([fname, date_str, total_str])
        except Exception as e:
            print(f"Error processing {fname}: {e}")
            ws.append([fname, None, None])

    wb.save(OUTPUT_FILE)

if __name__ == "__main__":
    process()
EOF
